from fractions import Fraction
from eab.construction import vector_rational, norm_rational
def bad():
    g=(None for p in [vector_rational((Fraction(1, 2**1075), Fraction(1, 2**1075)), allow_underflow=True)])
    next(g)
    return norm_rational(g.gi_frame.f_locals["p"])

